var t=[{title:`Banken voor steun en persen`,text:`Een vlakke bank ondersteunt persen, rows en zittende bewegingen. Een verstelbare bank verandert je rompshoek voor persen en andere oefeningen. Controleer of de vermelde capaciteit jou plus eventueel extra gewicht dekt, vergrendel de verstelling en zorg dat hij niet schommelt of schuift voordat je hem belast. Een stoel is niet automatisch een veilige gewichtsbank.`},{title:`Een stabiele step`,text:`Step-ups, incline push-ups en conditiewerk op een lage step vragen om een platform dat niet kantelt. Begin met een lage step waarop je heup en knie beheerst kunnen bewegen. Zet je hele steunvoet op de step, stap bewust naar beneden en duw niet af met de achterste voet om een te hoog platform te verbergen.`},{title:`Een springtouw afstellen`,text:`Ga als grove eerste controle met één voet midden op het touw staan en til de handvatten op. Veel recreatieve touwen passen als de handvatten ongeveer tot je onderste borst of oksels komen, al veranderen het ontwerp van het touw en je vaardigheid de ideale lengte. Een te kort touw raakt je voeten. Een te lang touw blijft aan de grond haken en kan leiden tot grote armcirkels.`},{title:`Controleer de ruimte en de uitrusting`,text:`Gebruik een antislipvloer en let op meubels, lampen, ventilatoren en andere mensen. Touwtjespringen heeft ruimte boven en naast je nodig, naast vloerruimte. Controleer vóór elke training op versleten touwcoatings, scherpe draaduiteinden, beschadigde bankscharnieren en losse stepoppervlakken. Vervang kapotte uitrusting in plaats van te improviseren met reparaties.`},{title:`TrainUp gebruiken`,text:`Stel in Profiel je banktype, vloeroppervlak, plafondhoogte, ondergrond en of springen mag in, en het schema kiest alleen oefeningen die daarbij passen. Sluiten je knieën of ruimte een step uit, of sluiten geluid, impact of plafondhoogte het touw uit, dan zijn oefeningen zonder step en stilstaand marcheren de alternatieven.`}];var i=[{label:`ACE-oefeningenbibliotheek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: veiligheid en techniek bij krachttraining`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`},{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var a={sections:t,sources:i};export{a as default,t as sections,i as sources};